/** Minutes past the end of the promised window before a stop counts as late. */
export const GRACE_MINUTES = 15;

/** A stop is late once its delivery, or now if it hasn't arrived, is past its window plus the grace. */
export const isLate = (stop: Stop, now: number) =>
  (stop.deliveredAt ?? now) > stop.windowEnd + GRACE_MINUTES * 60_000;

/** One alert per stop, and only to customers who opted in to delivery texts. */
export const shouldAlert = (stop: Stop, now: number) =>
  isLate(stop, now) && !stop.alertSent && stop.customer.textsOptIn;

