import { shouldAlert } from "./lateDelivery";

export const sendLateAlerts = async (stops: ReadonlyArray<Stop>, now: number, sms: Sms) => {
  for (const stop of stops)
    if (shouldAlert(stop, now)) {
      await sms.send(stop.customer.phone, `Your delivery is running late. New ETA: ${stop.eta}`);
      stop.alertSent = true;
    }
};

